tableData:
{{
  (function() {
    const poolData = Array.isArray(Get_Achats_Pool.data) ? Get_Achats_Pool.data : [];
    const selectedFournisseur = List_Fournisseurs.selectedItem?.ID_Fournisseur;
    const currentTab = appsmith.store.tab_achats || 'A_COMMANDER';

    let data = poolData;

    // 1. Filtrage par le fournisseur sélectionné à gauche (CONSERVÉ)
    if (selectedFournisseur && selectedFournisseur !== 'TOUS') {
      data = data.filter(row => {
        const idF = row.ID_Fournisseur || 'NON_ASSIGNE';
        return idF === selectedFournisseur || row.Nom_Fournisseur === List_Fournisseurs.selectedItem?.Nom_Fournisseur;
      });
    }

    // 2. Filtrage par onglet actif (CONSERVÉ)
    if (currentTab === 'A_COMMANDER') {
      data = data.filter(r => ['À COMMANDER', 'A COMMANDER'].includes((r.Statut_Achat || '').toUpperCase()));
    } else if (currentTab === 'EN_COMMANDE') {
      data = data.filter(r => ['COMMANDÉ', 'COMMANDE', 'REÇU PARTIEL', 'RECU PARTIEL'].includes((r.Statut_Achat || '').toUpperCase()));
    } else if (currentTab === 'HISTORIQUE') {
      data = data.filter(r => ['REÇU', 'RECU'].includes((r.Statut_Achat || '').toUpperCase()));
    }

    // 3. Regroupement par Référence de commande + Tri par date de dernière réception
    if (currentTab === 'EN_COMMANDE' || currentTab === 'HISTORIQUE') {
      const groupes = {};
      data.forEach(item => {
        const ref = item.Numero_Commande_Fournisseur?.trim() || 'Sans référence';
        if (!groupes[ref]) groupes[ref] = [];
        groupes[ref].push(item);
      });

      // Calcul de la date la plus récente par groupe (dernière pièce reçue)
      const listeGroupes = Object.keys(groupes).map(ref => {
        const items = groupes[ref];
        const maxDate = items.reduce((max, item) => {
          const t = new Date(item.Date_Reception || item.Date_Commande || item.Date_Demande || 0).getTime();
          return t > max ? t : max;
        }, 0);
        return { ref, items, maxDate };
      });

      // Tri des commandes : la plus récente (ou le dernier reliquat reçu) remonte en premier
      listeGroupes.sort((a, b) => b.maxDate - a.maxDate);

      const dataGroupes = [];
      const prefixe = currentTab === 'HISTORIQUE' ? '✅ COMMANDE REÇUE' : '🚚 COMMANDE';

      listeGroupes.forEach(g => {
        // Entête de groupe d'origine (CONSERVÉ À L'IDENTIQUE)
        dataGroupes.push({
          ID_Ligne_Achat: `HEADER_${g.ref}`,
          isHeader: true,
          Ref_Fournisseur: '',
          Article_Designation: `${prefixe} : ${g.ref} (${g.items.length} article${g.items.length > 1 ? 's' : ''})`,
          Prix_Achat: null,
          Quantite_BL: null,
          Quantite: null
        });

        // Tri interne des articles du groupe (du plus récent au plus ancien)
        const itemsTries = [...g.items].sort((a, b) => {
          const tA = new Date(a.Date_Reception || a.Date_Commande || 0).getTime();
          const tB = new Date(b.Date_Reception || b.Date_Commande || 0).getTime();
          return tB - tA;
        });

        dataGroupes.push(...itemsTries);
      });

      return dataGroupes;
    }

    return data;
  })()
}}
